from pathlib import Path
import csv, json, hashlib

BASE = Path(r'E:\Project\FlexPPI\experiments\_sources')
OUT = BASE / 'candidate_case_atlas_20261021' / 'evidence'
OUT.mkdir(parents=True, exist_ok=True)
cases = []

def add(id, title, pdbs, paragraphs, sources, status='已复算候选', category='TCR–pMHC'):
    cases.append(dict(id=id, title=title, pdbs=pdbs, category=category, status=status,
                      paragraphs=paragraphs, sources=sources))

def source(doi, title, local, url=None):
    p = BASE / local
    return dict(doi=doi, title=title, url=url or f'https://doi.org/{doi}', local=str(p),
                exists=p.exists(), sha256=hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None)

add('MEL5_AFFINITY', 'MEL5亲和成熟：同一接触片区的侧链取向与主链约束', ['3HG1','4JFF'], [
'MART-1（又称Melan-A）是黑色素细胞分化抗原，也是黑色素瘤T细胞识别的经典对象。本例固定HLA-A*02:01及其呈递的MART-1修饰十肽ELAGIGILTV，比较天然受体MEL5与由其直接亲和成熟获得的α24β17。该十肽含A27L锚定位点修饰，并非肿瘤特异突变。Madura等通过噬菌体展示筛选、表面等离子体共振（SPR）、X射线晶体学及变温SPR研究这一对照：解离常数由18 μM降至0.6 nM，主要动力学特征之一是解离明显减慢。总体对接姿态和肽构象相似，而MHC接触数由56增至97，肽接触数仅由39增至42；βCDR2的总pMHC接触由6增至38。因此，模型面对的问题不是从结构重新预测亲和力，而是定位增强的界面接触对应到哪些局部动态约束。',
'模型在完整六条识别环的45个主链位置上给出两状态绝对RMSF，其中βCDR2的全部5位均降低，均值从0.896降至0.636 Å；βCDR3的全部13位也降低，均值从0.801降至0.648 Å。侧链分析放在序列完全相同的pMHC一侧：完整界面23个有效Hχ位置中，17位下降、6位上升，说明模型预测的是局部状态重排，而非界面统一变硬。HLA Q72的Hχ由1.792降至1.375 nats；与其相邻的未替换βGly54主链RMSF由1.118降至0.747 Å。在保留各状态pMHC原坐标而移去TCR输入的计算对照中，Q72的Hχ差值从−0.417变为+0.104 nats，支持完整模型确实使用了对侧受体环境的信息。',
'已有三条独立200 ns轨迹为这一局部解释提供了额外依据。Q72侧链与βGly54的4 Å近接触占据率由平均24.4%升至97.4%；Q72末端酰胺与Gly54主链羰基氧满足氢键几何的帧比例由0.9%升至42.8%，Q72羰基氧与βIle53/Phe53主链酰胺满足氢键几何的比例由0.07%升至82.0%。工程状态约37.1%的帧同时满足两端几何条件。结合原文βIle53→Phe53增加界面接触的结构观察，可推断亲和成熟重塑了βCDR2–HLA接触片区，使Q72取向更集中，同时对邻近Gly54骨架形成更多局部约束。这为原研究较慢解离的界面提供了残基层面的动态解释，证据来源分别是模型预测、既有轨迹接触几何与原研究结合实验。',
'这一案例能够论证模型以互补读数定位同一识别界面的侧链和骨架响应，不能单独证明Q72的Hχ下降导致Gly54的RMSF下降。受体共有19处氨基酸变化，邻近βGly52→Pro52也可能直接影响环的骨架偏好，现有对照不能把全部效应归给某一条氢键。六环中αCDR2存在与轨迹相反的平均响应，因此结论应聚焦主要β环和同序列pMHC界面。Hχ是已结合态侧链取向多样性，不是结合熵；原文强调的有利溶剂重排也不由本模型计算。模型尚不能给出三万倍亲和力差异的自由能来源，或从这些已结合态读数推出细胞功能。'
], [source('10.1074/jbc.M113.464560','T-cell Receptor Specificity Maintained by Altered Thermodynamics','tcr_expanded_screen_v41_20261017/biology_sources/mel5_thermodynamics_2013.md','https://pmc.ncbi.nlm.nih.gov/articles/PMC3696650/')])

add('SB27_SB47','SB27与SB47：同一超长病毒肽的不同识别足迹',['2AK4','4JRY'],[
'Epstein–Barr病毒BZLF1抗原来源的13肽LPEPLPQGQLTAY由HLA-B*35:08呈递；其长度超过多数MHC-I肽，使中央部分突出结合槽。SB27与SB47是识别同一pMHC的不同天然TCR，并不存在亲本与改造体关系。Liu等以晶体结构、SPR及肽逐位替换后的细胞杀伤反应说明：SB27跨在中央突起上，SB47则绕过中央突起、将识别重心移到肽N端及MHC表面。SB27对P4、P6和P7替换敏感，而SB47较能耐受P7–P12替换。该背景提出直接的动态问题：改变识别足迹后，同一条肽的中央主链与侧链是否获得不同约束。',
'模型预测Q7的RMSF由SB27环境中的0.850升至SB47环境中的1.449 Å，Hχ由1.726升至2.825 nats，使同一残基的骨架运动与侧链取向多样性共同指向较弱限制。保留完整13肽时，模型与已有轨迹的RMSF变化排序相关为0.945；11个有效侧链位置的Hχ变化相关为0.321，说明侧链证据主要是局部而非整肽同样清楚。移去各输入中的TCR、保留pMHC坐标后，Q7的Hχ预测分别约为2.680和2.663 nats，原有明显差异接近消失，进一步显示模型对同一侧链的读数依赖识别伙伴。',
'这一结果可与原文中央敏感位点及不同识别足迹联系：SB27对中央突起的包围使Q7及相邻肽骨架受到较集中限制；SB47的识别重心转向N端后，Q7仍可能间歇接触受体，但允许更多骨架和取向选择。已有三重复轨迹中，Q7的主链及侧链多样性均增加，支持这种方向性解释。这里应使用“取向约束改变”而不是“SB47完全不接触Q7”；轨迹中SB47两条重复的Q7–TCR接触占据仍接近99%，另一条约58%，接触存在本身不能代表同样的角度限制。',
'该例适合论证模型区分相同抗原在不同受体识别环境下的局部动态，并以RMSF与Hχ解释识别足迹差异。它不能把跨两个天然TCR的差异归因于某个单点变化，也不能由Q7读数预测肽替换后的细胞杀伤曲线。Q9等位置没有同样好的侧链结果，完整侧链区域应与Q7并列保留。现有输入控制仅移去结构信息，未模拟真实解离；这些对照支持模型环境敏感性，不直接测定亲和力或受体生理功能。'
], [source('10.1074/jbc.M112.447185','Highly Divergent T-cell Receptor Binding Modes Underlie Specific Recognition of a Bulged Viral Peptide Bound to a Human Leukocyte Antigen Class I Molecule','tcr_case_v40_20261017/biology_sources/sb27_sb47_primary_jbc_2013.md','https://pmc.ncbi.nlm.nih.gov/articles/PMC3668706/')])

add('JM22_F5L','JM22识别流感M1 F5L：单点抗原变化后的局部动态',['1OGA','5HHM'],[
'流感A病毒M1蛋白的58–66位肽GILGFVFTL由HLA-A*02:01呈递，是人CD8 T细胞识别的保守表位。公共受体JM22可以交叉识别一些自然出现的变体，本例固定TCR与HLA，将肽P5由Phe替换为Leu，形成GILGLVFTL。Valkenburg等采用T细胞反应、SPR、pMHC热稳定性和晶体结构研究这一变化：WT的KD为1.79±0.5 μM，F5L大于200 μM；两种pMHC熔解温度近似相同，约65.8与65.6 ℃。结合态变体通过诱导契合形成近似原肽的构象，因此静态结合结构接近并不意味着受体识别代价相同。',
'排除发生化学类型替换的P5后，完整8个未替换肽主链位置的变化排序相关为0.714，6个有效侧链位置为0.657；两项变化误差相对一律预测不变分别改善22.0%和12.3%。不过模型在邻近位置的响应偏弱：F7的Hχ仅由0.792升至0.830 nats，已有三重复轨迹的平均升幅为0.495 nats；V6的模型升幅约0.027 nats，轨迹约0.204 nats。模型给出了部分相同方向的局部环境响应，却尚未充分区分这些未替换位置的取向多样性变化。',
'该例可以用来检验模型是否在抗原单点变化之外感知相邻未替换骨架和侧链的环境响应。原研究的诱导契合解释提供生物学背景，已有轨迹中的F7、V6取向范围扩大和T8接触占据降低提供动态线索。但原文游离pMHC到结合态的构象重排不是两种已结合复合物Hχ差异的测量，不能把两者直接等同。P5的Phe与Leu本身具有不同侧链状态空间，P5熵差需单列，不能承担环境敏感性论证。由于主要未替换位置的模型变化量很小，本例适合作为弱响应及幅度分辨能力的案例，不能据此声称模型解释了超过百倍的亲和力下降。'
],[source('10.1073/pnas.1603106113','Molecular basis for universal HLA-A*0201-restricted CD8+ T-cell immunity against influenza viruses','tcr_expanded_screen_v41_20261017/biology_sources/flu_M1_crossreactivity_2016.md','https://pmc.ncbi.nlm.nih.gov/articles/PMC4843436/')])

add('KRAS_G12D','KRAS G12D：埋藏突变与相邻肽骨架的动态约束',['7OW5','7OW6'],[
'KRAS是调控细胞增殖信号的小GTP酶，其G12D驱动突变可形成肿瘤新抗原。本例固定同一工程TCR JDIa41b1及HLA-A*11:01，比较十肽VVVGAGGVGK与VVVGADGVGK；蛋白G12D对应肽P6的Gly→Asp。Poole等以SPR测得同一TCR对WT和G12D的KD分别约3.0 μM与743±18 pM，并用晶体结构、变温SPR和MD能量分析研究这一强选择性。两种TCR对接姿态相似，D6侧链却埋入HLA沟槽，形成与R114的盐桥及与Q70的氢键，R114还受D116稳定。',
'模型的RMSF差异集中在肽中央及C端一侧：P6由1.080降至0.718 Å，邻近未替换G7由1.246降至0.904 Å，A5与V8亦降低，前3个位点读数相近。完整10肽主链变化排序相关为0.806，相对一律预测不变的误差改善38.9%；排除P6后，9个未替换位置仍为0.733和40.2%。这说明模型识别的局部响应并非仅来自突变位置，而延伸到原结构中与TCR形成极性接触的A5、G7等肽骨架。',
'结合原研究可提出具体机制：D6–HLA新增的相互作用加强了肽中央的局部约束，相邻骨架因此更容易维持与TCR配对的接触几何；这与模型定位到的中央骨架波动降低相一致。原文变温SPR与MD能量分解显示，更有利的焓及静电贡献抵消了更大的有序化代价。模型补充的是这些约束落在哪些残基，而非重算热力学。原文计算为25条4 ns模拟及MM/PBSA，当前独立动态对照来自ITrace每状态3条200 ns轨迹，两者来源不同。',
'Hχ对这一例的增量有限。原文预定义的Q70、R114、D116网络中，模型Hχ变化分别为−0.182、+0.020和−0.156 nats，不能概括成整个盐桥网络统一更有序；R114的近零响应尤其不支持“完整恢复网络侧链约束”。WT肽P6为Gly且多个中央位置没有可定义χ角，不能用这些位置的Hχ占位输出解释物理变化。模型能够定位局部主链响应，不能由较低RMSF证明亲和力提高、计算结合自由能或量化盐桥能。原研究更高成熟度JDIa96b35–抗CD3融合体的细胞功效也不能直接归给本结构对照。'
],[source('10.1038/s41467-022-32811-1','Therapeutic high affinity T cell receptor targeting a KRASG12D cancer neoantigen','tcr_case_v40_20261017/biology_sources/kras_g12d.md','https://pmc.ncbi.nlm.nih.gov/articles/PMC9464187/')])

add('PIK3CA_TCRS','PIK3CA H1047L：不同TCR识别同一共享新抗原',['7L1D','7RRG'],[
'PIK3CA编码PI3Kα催化亚基，其H1047L为常见肿瘤驱动变化。该替换在HLA-A*03:01呈递的九肽ALHGGWTTK中成为P2锚定位点；原研究通过免疫肽组学、细胞反应、SPR、热稳定性及晶体结构，证明突变肽具有较强呈递稳定性，并筛得多种识别受体。本例比较21LT2-2与0606T1-2识别相同突变肽–HLA的复合物。它是两个天然受体环境的比较，不是H1047 WT与L突变的比较，也不是受体亲本与成熟体。',
'原研究发现该肽中央表面主要由骨架构成；两种受体均诱导P6 Trp重新定位，其中长CDR3β受体将接触延伸至P8和肽C端，而另一受体更集中于中央。模型分析因此优先在能自然逐位置对应的同序列pMHC界面进行，保留33个RMSF位置及26个Hχ位置。其变化排序相关为0.545与0.724，变化误差相对一律预测不变改善5.4%与15.9%。Q72的模型Hχ下降约0.177 nats，已有轨迹平均下降约0.662 nats，且后三条轨迹均低于前三条，提供一处方向明确但模型响应较小的局部结果。',
'该例能够论证不同识别足迹对应同一pMHC侧链环境重排，模型具有一定分辨能力；侧链结果比自然界面主链误差改善更有力。两个受体的CDR长度和序列不同，少量对齐到同一氨基酸的TCR位置并非天然的一一生物对应。此前全界面主链误差改善中约90.6%来自这些跨TCR配对点，故不能把全界面的较好统计转述成相同pMHC整体动态均准确。三重复中许多侧链位置差异仍有较大波动，也没有形成像MEL5 Q72–Gly54那样经过局部接触复核的双读数机制链。模型尚不能从这些读数解释原文不同受体的杀伤效率，或证明突变导致抗原呈递增强；后者需要WT pMHC及其稳定性实验，属于另一项对照。'
],[source('10.1038/s41591-022-01786-3','Immunogenicity and therapeutic targeting of a public neoantigen derived from mutated PIK3CA','tcr_expanded_screen_v41_20261017/biology_sources/pik3ca_public_neoantigen_2022.md','https://pmc.ncbi.nlm.nih.gov/articles/PMC9117146/')])

series = list(csv.DictReader((BASE/'itrace_case_search_only_20261017/biology_first/biology_first_ITrace_candidate_series.csv').open(encoding='utf-8-sig')))
def bio_source(id):
    row = next(x for x in series if x['case_id']==id)
    paths=[]
    for loc in row['source_local'].split(';'):
        p=(BASE/'itrace_case_search_only_20261017/biology_first'/loc).resolve()
        if p.exists(): paths.append(p)
    p=paths[0] if paths else None
    return dict(doi=row['source_doi'],url=row['source_url'],title=row['system'],local=str(p) if p else '',
                exists=bool(p), sha256=hashlib.sha256(p.read_bytes()).hexdigest() if p else None)

add('B01','MAGE-A10 c728→c796：受体单点成熟的抗原环境响应',['7PDW','7PBC'],[
'MAGE-A10属于癌睾抗原，HLA-A*02:01呈递的GLYDGMEHL肽是工程TCR研究对象。c796由c728直接衍生，仅有βCDR1 E31D变化；原研究采用SPR、结构及选择性替换筛查，报道约六倍亲和力增加。固定受体大部分序列及同一pMHC，使其适合检验受体单处变化能否传递到未改变的抗原界面。另一个c756受体来自不同亲本，不能作为c728的后续双点成熟状态。',
'现有完整肽7个有效Hχ位置的变化排序相关为0.643，误差相对预测不变改善15.7%，但只有1个位点的MD均值变化超过两倍重复标准误；另一既有Full模型的相关为0。这说明单模型中存在一些侧链变化线索，尚未形成稳定的整肽结论。应同时保留六环与完整界面，而不因某个位点较好就认定工程机制被重现。',
'该例的价值在于干净的单点亲本关系，当前缺点在于动态信号较弱及模型间复现不足。模型目前不能把亲和力提升具体归给E31D引起的某条动态路径，也不能用已结合态Hχ代替原文溶剂排除或结合熵解释。已知游离c728晶体结构不等于已有游离态轨迹；缺少对应动态对照时，不应推断完整的结合前后预组织代价。'
],[bio_source('B01')])

add('B02','AHIII12.2：改变HLA接触环境的四状态系列',['1LP9','2J8U','2JCC','2UWE'],[
'AHIII12.2是识别人HLA-A2–ALWGFFPVL复合物的异种反应TCR。本系列保持TCR和肽不变，分别比较HLA WT、K66A、W167A和T163A，原研究采用SPR、晶体结构、细胞杀伤及WT/K66A的直接ITC对照。平衡KD依次为9.3、31.8、15.4和4.7 μM；K66A伴随明显CDR3α构象改变及最低细胞杀伤，另两种变化提供程度不同的对照。',
'模型可检验HLA环境改变是否对应未替换TCR识别环与肽的动态响应。现有完整六环48位主链比较中，K66A的变化排序相关为0.406、相对预测不变误差改善10.7%，W167A为0.223和3.1%；T163A为0.033且误差增加9.4%。另一既有Full模型没有复现K66A的优势，因此目前不能认为模型整体恢复了四状态的动态顺序。',
'该系列实验设计有力，但当前模型支持有限，应作为环境扰动响应不足的完整案例。不能删去T163A或W167A以强化K66A叙述。当前没有相应游离态轨迹，结合态Hχ不能解释ITC结合熵；原文K66A焓的具体符号还需对照表格与文本一致性，因此文档只采用焓贡献明显改变这一背景，不引用未经一致核实的精确热值。'
],[bio_source('B02')])

add('B03','1G4识别NY-ESO-1 C9V：锚定位点与识别界面',['2BNR','2BNQ'],[
'NY-ESO-1是癌睾抗原，1G4受体识别其HLA-A2呈递肽SLLMWITQC。C9V替换形成SLLMWITQV，在保持TCR与HLA不变时改变肽末端锚定环境。原研究通过SPR、肽–HLA结合、晶体结构和细胞突触/杀伤颗粒实验，报道TCR KD由13.3降至5 μM，同时肽的HLA结合及颗粒极化表现改善。因此模型问题是：埋藏锚点变化是否在未替换识别界面产生可分辨动态响应。',
'现有整肽9位主链变化排序相关为−0.117，误差比预测不变增加16.7%，另一既有Full模型也未改善；三重复中未见整肽位置的均值变化超过两倍重复标准误。该结果既包含模型对细微变化分辨不足，也反映当前轨迹中主链变化本身较弱，不能作为成功机制实例。',
'此例适合保留为生物差异明确、当前动态模型信息有限的候选。P9从Cys变为Val直接改变侧链化学类型，必须单列，不能把其Hχ差异当作相同侧链环境预测能力。单独的结合态动态读数也不能区分HLA加载稳定性、TCR结合及细胞反应对功能增强的不同贡献；当前数据不足以建立从锚点到识别环的特定残基通路。'
],[bio_source('B03')])

add('B04','N17.1.2交叉识别NRAS Q61K与Q61R',['8YIV','8YJ2'],[
'NRAS是RAS家族信号蛋白，Q61K和Q61R均可产生肿瘤新抗原。本例固定N17.1.2受体及HLA-A*01:01，比较十肽ILDTAGKEEY与ILDTAGREEY，变化位于肽P7。原研究以SPR、细胞抗原反应及共晶结构说明同一受体可识别两种新抗原，KD为1.2±0.1与3.4±0.2 μM；这是一对均被识别的肿瘤变体，而非WT逃逸与突变识别的结构对照。',
'模型可以检验相同TCR对Lys/Arg替换的局部适应是否扩展到未替换肽及识别环。当前全六环50位主链变化排序相关为−0.365，误差比预测不变增加38.4%；另一既有Full模型同样不佳。这些结果尚不能支撑模型恢复两种新抗原对应的整体环动态差异。',
'该案例生物关系明确，当前模型证据弱，适合记录交叉识别问题而非写成成功解释。P7的Lys/Arg不同，Hχ差异包含侧链本身的状态空间变化；对模型环境敏感性的判断应放在其余9个肽位置和未替换界面。没有WT受体结合结构及匹配轨迹，不能由这两个新抗原的比较解释WT不被识别的原因，也不能从两种已结合态的动态值推出三倍KD差异。'
],[bio_source('B04')])

add('B05','PRAME S2跨HLA-A3/A11识别：固定抗原与TCR的呈递环境对照',['8RYM','8RYN'],[
'PRAME是肿瘤相关抗原，ELFSYLIEK肽可由相关HLA等位型呈递。本例固定S2 WT受体及肽，比较HLA-A*03:01与HLA-A*11:01。原研究以SPR、晶体结构及HLA位点替换实验研究等位型选择性，KD分别为21和72 μM；HLA163的Thr/Arg差异是直接接触识别的多态决定因素之一，但两等位型还存在其他差别，不能简化为单个HLA163突变实验。',
'在自然逐位置对应、氨基酸类型相同的pMHC界面15个Hχ位置中，模型变化排序相关为0.486，误差相对预测不变改善14.3%；另一既有Full模型为0.686和24.1%。5个位点的MD均值变化超过两倍重复标准误，主模型其中4位方向一致，提示可比较的同类型界面侧链响应。',
'这个对照支持模型在呈递环境变化下辨认部分侧链状态差异，但链内模型在相同集合的相关为0.671、误差改善14.7%，并未显示完整模型具有额外优势。因此不能将本例用作链间信息必要性的证明，也不能把HLA等位型偏好完全归因于某个侧链熵变化。它与S2工程成熟属于不同问题，文档中应分别成例。'
],[bio_source('B05')])

add('B06','KRAS G12V 4TCR2→MH：亲本受体工程对照',['8WTE','8WUL'],[
'KRAS G12V可在HLA-A*11:01上形成VVGAVGVGK新抗原。本例固定相同肽–HLA，比较4TCR2亲本及已发表的MH衍生受体。原研究通过SPR和共晶结构报道，两处TCRβ替换带来约15倍亲和力提高，MH的KD约2 μM，同时保留对WT肽的区分。与WT/G12D抗原替换不同，这里的变化发生于受体。',
'模型可以检验亲和成熟后未改序列的pMHC与识别环骨架是否出现可分辨响应。当前全六环48位主链变化排序相关为−0.507，误差比预测不变增加60.7%；另一既有Full模型也未改善。现有数据中MD平均变化较小，约0.069 Å，当前模型未能稳定分辨其空间模式。',
'该例暂不能支持模型解释工程亲和力提高。当前结构还含恒定区截短或缺失差别，需将其与真实可变区替换区分；按整链配准的RMSF可能同时受到构建体差异影响。不能把缺失残基算为工程变化，也不能仅凭两种复合物结合姿态接近便将所有动态差值归给两处替换。'
],[bio_source('B06')])

add('B08','PRAME S2→S2-198：亲和增强与等位型偏好扩大',['8RYM','8RYO'],[
'本例固定HLA-A*03:01与PRAME肽ELFSYLIEK，比较S2 WT及CDR1α工程受体S2-198。原研究SPR显示对A3的KD由21 μM降至76 nM，且对A3相对A11的偏好进一步扩大，与试图获得广泛等位型识别的目标形成有意义的机制问题。结构和HLA替换对照表明工程位置与多态呈递表面的关系重要。',
'现有完整CDR3的23个主链位置中，主模型变化排序相关为0.559、误差相对预测不变改善37.2%，但另一既有Full模型的误差反而增加4.1%。侧链虽有约0.55–0.59的变化排序相关，16个位置均未见MD均值变化超过两倍重复标准误。主链存在单模型线索，侧链暂缺稳定幅度支持。',
'本例可展示受体工程后动态响应的模型依赖性，尚不能建立“某位点Hχ改变使A3选择性增强”的残基机制。等位型偏好需要A3和A11两种背景都保留；仅比较A3两状态不能解释选择性扩大。另一个S8系列的8RYP/8RYQ同时改变受体和HLA，不能混入本例当作同一背景下的亲本成熟对照。'
],[bio_source('B08')])

add('B09','MEL5识别MART-1十肽与九肽：不同锚定方式的构象适应',['4QOK','6EQA'],[
'MART-1在HLA-A*02:01上可形成天然十肽EAAGIGILTV和九肽AAGIGILTV。两种肽既有长度差异，也涉及N端锚定方式。本例保持MEL5及HLA不变；原研究通过晶体学、核磁共振及热力学分析提出，结合态九肽可采用不同N端构型，MEL5能够促使其改变锚定。因此这是一项与构象可塑性直接相关的应用问题。',
'模型可检验长度与锚定改变是否在相同受体识别环和MHC环境中形成可分辨动态响应。当前完整六环45位主链变化排序相关为−0.149，误差比预测不变增加13.1%，另一既有Full模型也未改善。现有结果不足以将原研究的替代锚定机制变成模型成功案例。',
'该对照不能按肽位置编号直接相减，需明确九肽与十肽的序列配准及插入位置；不同晶体替代占据也可能只在当前静态输入中保留其中一种。模型给每个残基一个RMSF和Hχ摘要，不能直接预测两种锚定构型的转换路径或占据率。6EQB是α24β17结合九肽，不是游离MEL5状态，也不应被当成缺失的apo对照。'
],[bio_source('B09')])

add('B10','DMF4与DMF5平行系列：MART-1长短肽的受体依赖响应',['3QDG','3QDJ','3QDM','3QEQ'],[
'DMF4与DMF5是识别MART-1的两个不同天然TCR，各自均可比较HLA-A2上的修饰十肽ELAGIGILTV与九肽AAGIGILTV。原研究SPR及配对晶体结构显示，DMF5的KD为6与40 μM，DMF4为29与170 μM。DMF5以相对共有的开放构型结合两种肽，DMF4则改变对接方向。两个平行受体系列使模型能够检验抗原长度改变的环境响应是否依赖受体。',
'DMF4系列在自然pMHC界面19个同类型Hχ位置的变化排序相关为0.779，误差相对预测不变改善25.2%；另一既有Full模型为0.553和27.1%。7个位点的MD均值变化超过两倍重复标准误，主模型7位方向均一致。DMF5平行对照在相应16位区域却为−0.144，误差增加24.3%，因此成功证据只属于DMF4特定界面，不能扩展为两种受体共享的统一规律。',
'本例能够讨论模型在一种受体背景下辨认呈递界面的侧链重排，并通过平行失败显示受体背景的适用范围。长度与锚定氨基酸同时改变，无法分离各自贡献；两个TCR也不是工程前后关系。原研究临床和细胞背景不能由本例动态值重现，更不能从DMF4局部Hχ预测出DMF5更高杀伤或毒性。完整四状态图应保留两个受体系列，才能公平呈现证据。'
],[bio_source('B10')])

add('B11','MEL5识别三种肿瘤抗原：交叉反应中的识别环主链响应',['4QOK','7Q99','7Q9A'],[
'同一MEL5受体除Melan-A的EAAGIGILTV外，还可识别HLA-A2呈递的IMP2肽NLSALGIFST及BST2肽LLLGIGILVL。Cell 2023研究结合生化、功能及复合物结构说明共享中央识别特征允许不同肿瘤抗原交叉识别，MEL5的功能反应层级为Melan-A、BST2、IMP2。该系列的生物问题是：同一识别骨架如何适应具有多个序列差异的抗原，而非单点变体导致的亲和成熟。',
'IMP2→BST2的完整CDR3共22个主链位置中，主模型变化排序相关为0.713、误差相对预测不变改善42.9%，另一既有Full模型为0.553与41.8%；4个较大MD均值变化位置的方向均预测一致。六环合并也保留14.4%的误差改善。但Melan-A→IMP2明显失败，Melan-A→BST2虽有0.824的CDR3排序相关，误差仍比预测不变高11.0%。三个抗原必须同列，才能看出模型只在特定对照上形成有用主链信息。',
'该例可论证模型在IMP2/BST2对照中定位同一受体骨架的不同约束，不能宣称已准确覆盖MEL5对三种抗原的全部动态适应。多处抗原替换使肽自身Hχ差异同时包含化学组成变化，当前侧链证据也较弱。7Q9B属于MEL8；原文较强的抗原敲除肿瘤杀伤证据主要针对MEL8，不能移用到MEL5。功能反应层级也不能由当前两项动态摘要直接预测。'
],[bio_source('B11')])

add('B12','1G4 CDR2亲和成熟：较强单模型响应与构建体问题',['2F54','2F53'],[
'1G4受体识别HLA-A2呈递的NY-ESO-1肽SLLMWITQC。c49c50是由1G4通过CDR2α/β亲和成熟获得的已发表受体，SPR显示可达约1 nM的结合亲和力，并在所测肽及细胞结合面板中保留选择性。固定pMHC、比较亲本与衍生受体，适合分析工程变化之外的未替换环及对侧界面是否发生协同约束。',
'当前主模型在完整六环49个主链位置上变化排序相关为0.680，误差相对预测不变改善59.7%；43个未替换位置为0.710与63.0%。但另一既有Full模型误差分别增加35.9%和45.8%，未形成跨模型重复的结果。当前输入中α链在工程CDR2以外也有缺失或构建差别，完整六环对应虽已建立，整链拟合所得RMSF仍可能受到构建差异影响。',
'本例具有值得追踪的未替换骨架响应，当前应标记为构建体和配准复核候选。需要对照原始SEQRES、作者编号及另一WT构建体2BNR，确认动态差值主要来自生物改变而非拟合参照差异。模型尚不能支持成熟受体所有环均更有序，也不能由可溶性亲和力或当前动态值推出细胞杀伤能力。'
],[bio_source('B12')],status='待构建体与拟合复核')

add('CATCHBOND','TCR156 S32M：力敏感识别的失败对照',['9NMU','9NMX'],[
'TCR156识别HLA-A*02:01呈递的前列腺酸性磷酸酶（PAP）肽TLMSAMTNL。Chen等的原始研究以catch-bond工程增强肿瘤自身抗原的功能识别，目标是保持较低生理亲和力而提高受力条件下的结合响应及细胞效能。本地已有WT与S32M的结构和每状态10条独立轨迹，适合检验模型能否从静态结合结构辨认这类工程后的局部动态变化。',
'复算20条现成轨迹并对照全部未替换位置后，407个RMSF位置的变化排序相关仅0.022，343个Hχ位置为−0.020；相对预测不变的误差分别增加57.6%和2.8%。准备结构与实验结构两套输入得到一致的弱结果，完整肽也未显示改善。该例没有给出可用于解释功能增强的模型动态模式。',
'这是一项应保留的适用边界案例：当前模型输出未能捕捉该工程对照的变化，不能因文献机制新颖就配上一条模型支持的通路。力依赖结合寿命需要受力实验或相应力学模拟；现有无外力条件下的RMSF及Hχ本身不计算catch bond。失败也不能反向否定原文机制，双方观察的物理量与实验条件不同。'
],[dict(doi='10.1126/science.adx3162',title='Overcoming T cell tolerance to tumor self-antigens through catch-bond engineering',url='https://doi.org/10.1126/science.adx3162',local=r'E:\Project\FlexPPI\artifacts\tcr_pmhc_reassessment_20260915\literature\chen2026.txt',exists=True)],status='已复算，当前不支持成功机制')

add('KIX','CBP KIX：共同活动环定位与状态差值的区分',['2AGH'],[
'CBP是参与基因表达调控的转录共激活因子，KIX为其结合不同转录激活片段的小型结构域。c-Myb与MLL可同时结合KIX两侧表面，原始NMR结构研究揭示其协同结合基础。本例从同一2AGH构象构建无伙伴、仅c-Myb、仅MLL及双伙伴四种组成，问题分为两个层次：模型能否定位KIX本身较活跃的L12环，以及能否辨认伙伴改变带来的细微状态差值。',
'在完整KIX的87位中，模型与每状态单条100 ns轨迹的残基RMSF排序相关为0.729–0.896，最高20%活动集合重合为61%–89%。双伙伴状态18个模型优先位置中14个命中，L12的8位有6位进入最高20%集合。该结果支持模型从静态结构识别共同的高活动环区，并提供用于挑选局部动态位置的排序。',
'四种组成共用初始KIX骨架，减少输入构象差异，却也限制其代表真实结合前后结构重排的程度。L12六对状态差值的预测方向均与单轨迹参考相反，因此本例不能作为模型恢复c-Myb/MLL协同动态变化或变构方向的证据。每状态只有一次生产轨迹，现有结果适合论证活动区定位，不能据此定量解释结合合作性或热力学自由能。'
],[dict(doi=None,title='De Guzman et al. Structural basis for cooperative transcription factor binding to the CBP coactivator. J Mol Biol 355:1005–1013 (2006).',url='https://www.rcsb.org/structure/2AGH',local=str(BASE/'mel5_joint_case_v49_20261019/manuscript_QA/v49_content.txt'),exists=True)],status='现稿已用，定位能力证据',category='现稿非TCR结构实例')

add('UBIQUITIN','泛素–UBA：同类型侧链取向多样性的预测',['2QHO'],[
'泛素是76个氨基酸组成的小蛋白，通过共价标记参与蛋白质降解等调控过程。EDD泛素连接酶的UBA结构域可非共价识别泛素；原始结构研究提供2QHO复合物。本例使用DynaRepo中相应完整两链轨迹，重点不是比较结合前后，而是在同一复合物内检验模型能否区分相同氨基酸类型在不同局部环境中的侧链多样性。',
'模型可给同一位置提供主链RMSF与侧链Hχ两个摘要。现稿展开泛素全部66个Hχ有效位置，并以Q2/Q41及其他谷氨酰胺的逐角MD占据作为具体说明；各位点χ1–χ4的分层分析包含66、52、23和10个有效位置。这里Hχ对应多个侧链角度组合的多样性，逐角曲线来自真实轨迹，不能画成模型直接预测了每条角度曲线。',
'该实例适合论证模型对同类型残基局部环境差异的分辨，而非泛素结合功能或UBA亲和力预测。模型每残基只有一个联合Hχ，不能从该值唯一恢复具体χ角、完整角度概率曲线或每个构象的占据率；不同分布可能具有相同熵。只有一个复合物和轨迹来源时，也无法把Q2/Q41差异推为全部泛素生理过程的机制。所有有效位点及不同角层的样本组成应保留，避免把选定残基作为整体表现。'
],[dict(doi=None,title='Kozlov et al. Structural basis of ubiquitin recognition by the ubiquitin-associated (UBA) domain of the ubiquitin ligase EDD. J Biol Chem 282:35787–35795 (2007).',url='https://www.rcsb.org/structure/2QHO',local=str(BASE/'mel5_joint_case_v49_20261019/manuscript_QA/v49_content.txt'),exists=True)],status='现稿已用，同类型侧链证据',category='现稿非TCR结构实例')

